// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address originEOA, address desiredOwner) public {
        vm.assume(originEOA != address(0));
        vm.assume(desiredOwner != address(0));
        ProxyCaller proxy = new ProxyCaller(address(c), desiredOwner);

        vm.deal(originEOA, 1 ether);

        bool ok;
        try c.setOwner(originEOA) { ok = true; } catch { ok = false; }
        assertTrue(ok);

        vm.prank(originEOA);
        try proxy.callSetOwner() { ok = true; } catch { ok = false; }
        assertTrue(c.owner() == originEOA);
    }
}

contract ProxyCaller {
    Owned public target;
    address public newOwner;
    constructor(address _target, address _newOwner) {
        target = Owned(_target);
        newOwner = _newOwner;
    }
    function callSetOwner() external {
        target.setOwner(newOwner);
    }
}
